static void toStreamRational(std::ostream& out,
                             const Rational& r,
                             bool isReal,
                             Variant v)
{
  bool neg = r.sgn() < 0;
  bool arithTokens = options::ioutils::getPrintArithLitToken(out);
  // Print the rational, possibly as a real.
  // Notice that we print (/ (- 5) 3) instead of (- (/ 5 3)),
  // the former is compliant with real values in the smt lib standard.
  if (r.isIntegral())
  {
    if (arithTokens)
    {
      if (neg)
      {
        out << "-" << -r;
      }
      else
      {
        out << r;
      }
      if (isReal)
      {
        out << "/1";
      }
    }
    else
    {
      if (neg)
      {
        out << "(- " << -r;
      }
      else
      {
        out << r;
      }
      if (isReal)
      {
        out << ".0";
      }
      if (neg)
      {
        out << ")";
      }
    }
  }
  else
  {
    Assert(isReal);
    if (arithTokens)
    {
      if (neg)
      {
        Rational abs_r = (-r);
        out << '-' << abs_r.getNumerator() << '/' << abs_r.getDenominator();
      }
      else
      {
        out << r.getNumerator() << '/' << r.getDenominator();
      }
    }
    else
    {
      out << "(/ ";
      if (neg)
      {
        Rational abs_r = (-r);
        out << "(- " << abs_r.getNumerator() << ") " << abs_r.getDenominator();
      }
      else
      {
        out << r.getNumerator() << ' ' << r.getDenominator();
      }
      out << ')';
    }
  }

